CREATE COLUMN TABLE "TEST_AP"."OPJT" ("DocEntry" INTEGER CS_INT NOT NULL , "TempType" NVARCHAR(1) DEFAULT 'N', "TempName" NVARCHAR(254), "LogInstanc" INTEGER CS_INT, "UserSign" INTEGER CS_INT, "UserSign2" INTEGER CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "UpdateDate" LONGDATE CS_LONGDATE, "TempDesc" NVARCHAR(254), PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OPJT_NAME" ON "TEST_AP"."OPJT" ( "TempName" ASC )